<?php declare(strict_types=1); ?>
<div class="grid-2"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Competitor-isolated sourcing</span><h2>Submit proposal</h2><p>You cannot view internal scoring, weights, alternative suppliers, or competing proposals.</p></div></header><?php if(supplier_portal_can($account,'sourcing')): ?><form class="form-grid" method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="submit_sourcing"><input type="hidden" name="return_tab" value="sourcing"><label><span>Sourcing reference</span><input name="sourcing_reference" required></label><label><span>Proposal title</span><input name="title" required></label><label><span>Bid deadline</span><input type="datetime-local" name="bid_deadline" value="<?= date('Y-m-d\TH:i',strtotime('+7 days')) ?>" required></label><label><span>Proposal value</span><input type="number" name="proposal_value" min="0" step="0.01"></label><label><span>Lead time days</span><input type="number" name="lead_time_days" min="0"></label><label><span>Revision</span><input type="number" name="revision_number" min="1" value="1"></label><label><span>Payment terms</span><input name="payment_terms"></label><label><span>Freight terms</span><input name="freight_terms"></label><label class="span-2"><span>Exceptions and assumptions</span><textarea name="exceptions_and_assumptions" required></textarea></label><label class="span-2"><span>Proposal document reference</span><input name="document_reference" required></label><div class="span-2"><button class="button primary">Submit and lock proposal</button></div></form><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Proposal history</span><h2>Locked submissions</h2></div></header><div class="record-list"><?php foreach($sourcing as $proposal): ?><article class="record-card"><header><div><strong><?= h($proposal['title']) ?></strong><small><?= h($proposal['sourcing_reference']) ?> · Revision <?= (int)$proposal['revision_number'] ?></small></div><span class="status <?= h($proposal['status']) ?>"><?= h(status_label($proposal['status'])) ?></span></header><p><?= money($proposal['proposal_value']) ?> · <?= (int)$proposal['lead_time_days'] ?> days · <?= h($proposal['review_note']??'') ?></p></article><?php endforeach; ?></div></section></div>
